<?php
declare(strict_types=1);require __DIR__.'/includes/ui.php';$u=msw_require_user();$id=(int)($_GET['id']??0);$r=msw_one('SELECT r.*,a.username attacker,d.username defender FROM fob_raids r JOIN users a ON a.id=r.attacker_user_id JOIN users d ON d.id=r.defender_user_id WHERE r.id=? AND (r.attacker_user_id=? OR r.defender_user_id=?)','iii',[$id,(int)$u['id'],(int)$u['id']]);if(!$r){http_response_code(404);exit('Raid report not found.');}$tr=json_decode((string)$r['transfer_json'],true)?:[];$ds=json_decode((string)$r['defender_snapshot_json'],true)?:[];msw_header('FOB Raid Report','fob.php');?><section class="hero"><div class="eyebrow">AFTER ACTION REPORT #<?=$id?></div><h1><?=msw_e(strtoupper(str_replace('_',' ',$r['result'])))?></h1><p><?=msw_e($r['attacker'])?> infiltrated <?=msw_e($r['defender'])?>. Defender state was snapshotted at raid start, then the resource ledger was resolved atomically.</p></section><div class="grid g2" style="margin-top:18px"><?php msw_panel('Resource Transfer','EXACT LEDGER DELTA');?><table><tbody><?php foreach($tr as $k=>$v):?><tr><td><?=msw_e(ucwords(str_replace('_',' ',$k)))?></td><td><?=number_format((int)$v)?></td></tr><?php endforeach;?></tbody></table><?php msw_panel_end();msw_panel('Defender Snapshot','SECURITY STATE');?><p>Base: <b><?=msw_e($ds['user']['base_grade']??'--')?></b> · Power <?=number_format((int)($ds['user']['base_power']??0))?></p><p>Security: <?=number_format((int)($ds['security']['score']??0))?> · <?=msw_e($ds['security']['grade']??'--')?></p><p>Combat defenders: <?=count($ds['team']??[])?></p><?php msw_panel_end();?></div><a class="btn" href="<?=msw_e(msw_url('fob.php'))?>">Return to FOB Network</a><?php msw_footer();?>
